name: Claude Code Review

on:
  issues:
    types: [opened, edited, reopened]
  issue_comment:
    types: [created]
  pull_request:
    types: [opened, edited, reopened]
  pull_request_review_comment:
    types: [created]

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  claude-code-review:
    runs-on: ubuntu-latest
    if: |
      github.event_name == 'issues' && contains(github.event.issue.title, '@claude') ||
      github.event_name == 'issues' && contains(github.event.issue.body, '@claude') ||
      github.event_name == 'issue_comment' && contains(github.event.comment.body, '@claude') ||
      github.event_name == 'pull_request' && contains(github.event.pull_request.title, '@claude') ||
      github.event_name == 'pull_request' && contains(github.event.pull_request.body, '@claude') ||
      github.event_name == 'pull_request_review_comment' && contains(github.event.comment.body, '@claude')
    steps:
      - name: Check if user is collaborator
        id: check-collab
        uses: actions/github-script@v7
        with:
          script: |
            const username = context.payload.sender.login;
            const owner = context.repo.owner;
            const repo = context.repo.repo;

            try {
              const { data } = await github.rest.repos.checkCollaborator({
                owner,
                repo,
                username
              });
              return true;
            } catch (error) {
              if (error.status === 404) {
                return false;
              }
              throw error;
            }
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

      - name: Skip if not collaborator
        if: steps.check-collab.outputs.result != 'true'
        run: |
          echo "User is not a collaborator. Skipping Claude Code review."
          exit 0

      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 1

      - name: Run Claude Code
        uses: anthropics/claude-code-action@beta
        with:
          anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}
          permissions:
            - FS:full
            - NET:external
          prompt: |
            You are assisting with the usetrmnl/trmnl-home-assistant repository.

            Context:
            - Event Type: ${{ github.event_name }}
            - Issue/PR Title: ${{ github.event.issue.title || github.event.pull_request.title || '' }}
            - Issue/PR Body: ${{ github.event.issue.body || github.event.pull_request.body || '' }}
            - Comment: ${{ github.event.comment.body || '' }}
            - Repository: ${{ github.repository }}
            - Branch: ${{ github.ref_name }}

            Please analyze the context and provide helpful assistance. If this is an issue, explore the problem and suggest solutions. If this is a PR, review the changes and provide feedback.
